//! Component dumps of the colour widgets: each one's resolved style (its pure `style` function) in
//! every built-in and mode, as text under `tests/dumps/components/`. Rewrite with
//! `UPDATE_DUMPS=1 cargo test -p craft-color --features ui --test control_dumps`.

use craft_color::ui::{ColorArea, ColorDisc, ColorWheel};

use craft_ui::testing::dump::{Dump, check_component};
use craft_ui::theme::UiTokens;

const HEADER: &str =
    "Generated by crates/color/tests/control_dumps.rs; rewrite with UPDATE_DUMPS=1 cargo test -p craft-color --features ui --test control_dumps";

fn check(file: &str, each: impl FnMut(&mut Dump, &UiTokens)) {
    check_component(format!("{}/tests/dumps/components/{file}", env!("CARGO_MANIFEST_DIR")), HEADER, each);
}

#[test]
fn color_parts() {
    check("color_parts.txt", |d, t| {
        let s = ColorArea::style(t);
        d.line("area", s.area)
            .line("area_height", s.area_height)
            .line("strip_full", s.strip_full)
            .line("strip", s.strip)
            .line("edge", s.edge)
            .line("marker_inner_radius", s.marker_inner_radius)
            .line("marker_inner", s.marker_inner)
            .line("marker_outer_radius", s.marker_outer_radius)
            .line("marker_outer", s.marker_outer)
            .line("pointer", s.pointer)
            .line("pointer_color", s.pointer_color);
    });
}

#[test]
fn color_wheel() {
    check("color_wheel.txt", |d, t| {
        let s = ColorWheel::style(t);
        d.line("side", s.side)
            .line("side_min", s.side_min)
            .line("ring_min", s.ring_min)
            .line("ring_max", s.ring_max)
            .line("ring_ratio", s.ring_ratio)
            .line("outer_inset", s.outer_inset)
            .line("triangle_inset", s.triangle_inset)
            .line("grab_outer", s.grab_outer)
            .line("grab_inner", s.grab_inner)
            .line("edge", s.edge)
            .line("marker_inner_radius", s.marker_inner_radius)
            .line("marker_inner", s.marker_inner)
            .line("marker_outer_radius", s.marker_outer_radius)
            .line("marker_outer", s.marker_outer);
    });
}

#[test]
fn color_ramp() {
    check("color_ramp.txt", |d, t| {
        let r = t.component.color_ramp;
        d.line("height", r.height)
            .line("height_min", r.height_min)
            .line("boxes", r.boxes)
            .line("boxes_gap", r.boxes_gap)
            .line("cells_x", r.cells_x as f32)
            .line("cells_y", r.cells_y as f32)
            .line("edge", ColorArea::style(t).edge);
    });
}

#[test]
fn color_disc() {
    check("color_disc.txt", |d, t| {
        let s = ColorDisc::style(t);
        d.line("side", s.side)
            .line("side_min", s.side_min)
            .line("inset", s.inset)
            .line("marker", s.marker)
            .line("marker_selected", s.marker_selected)
            .line("grab", s.grab)
            .line("floor", s.floor)
            .line("spoke", s.spoke)
            .line("edge", s.wheel.edge)
            .line("marker_inner", s.wheel.marker_inner)
            .line("marker_outer", s.wheel.marker_outer);
    });
}
